def shared_slow(a, b):
    steps = 0
    found = []
    for x in a:
        for y in b:
            steps += 1
            if x == y:
                found.append(x)
                break
    return len(found), steps


def shared_fast(a, b):
    steps = 0
    lookup = set(b)
    found = []
    for x in a:
        steps += 1
        if x in lookup:
            found.append(x)
    return len(found), steps


left = list(range(0, 400))
right = list(range(200, 600))
print(shared_slow(left, right))
print(shared_fast(left, right))

