independent-practice.solution:
def busiest_page(visits, pages):
    if not pages:
        return None
    counts = {}
    for visit in visits:
        counts[visit] = counts.get(visit, 0) + 1
    best = None
    best_count = -1
    for page in pages:
        total = counts.get(page, 0)
        if total > best_count:
            best = page
            best_count = total
    return best

